// Single source extracted verbatim from the existing compass configurator.
export const compassPreviewHalo=selector=>`${selector}::before{content:"";position:absolute;inset:4%;border-radius:50%;background:radial-gradient(circle,rgba(255,255,255,.40) 0%,rgba(255,255,252,.30) 20%,rgba(255,251,240,.18) 42%,rgba(255,247,230,.08) 60%,transparent 76%);filter:blur(16px);pointer-events:none;z-index:0}`;
export const compassDialogSurface=selector=>`${selector}{--picker-gold:#dfbc72;--picker-bright:#f7dfa1;box-sizing:border-box;width:min(560px,calc(100vw - 20px));max-width:calc(100vw - 20px);margin:auto;padding:18px 18px 15px;border:1px solid #c9a050;border-radius:13px;color:#d1d4d9;background:radial-gradient(ellipse at 10% 20%,#24313945,transparent 64%),#091219;box-shadow:0 24px 90px #000c,inset 0 0 0 3px #cda9500c;max-height:calc(100vh - 20px);overflow:auto;overscroll-behavior:contain;scrollbar-width:thin;color-scheme:dark}`;
